  "SecurityConfig": {
    "description": "SecurityConfig groups the login and data protections that do not depend on\ntwo-factor codes. It is one JSON setting that only owners may change.\nBackupPassphrase is a secret: stored encrypted, served blank, and kept when a\nsave leaves it blank (ClearBackupPassphrase empties it on purpose).",
    "properties": {
      "approvalActions": {
        "description": "PasskeyLoginEnable adds a passwordless sign-in with a user-verifying passkey;\nPasskeySecondFactor asks admins who have passkeys for one after the password.\nApprovalActions lists the sensitive actions that need a second admin's\napproval (see ApprovalActions); empty turns the gate off.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "backupPassphrase": {
        "type": "string"
      },
      "captchaEnable": {
        "type": "boolean"
      },
      "clearBackupPassphrase": {
        "type": "boolean"
      },
      "newLocationAlert": {
        "type": "boolean"
      },
      "passkeyLoginEnable": {
        "type": "boolean"
      },
      "passkeySecondFactor": {
        "type": "boolean"
      },
      "rotateSubSigningKey": {
        "type": "boolean"
      },
      "subSigningEnable": {
        "type": "boolean"
      },
      "subSigningKey": {
        "type": "string"
      },
      "tgLoginEnable": {
        "description": "With SubSigningEnable the subscription server only answers links carrying a\nvalid signature. The key is server-made and never served; rotating it\nvoids every link issued so far.\nTgLoginEnable asks admins with a linked Telegram chat for a one-time code\nafter the password, while the Telegram bot is running.",
        "type": "boolean"
      }
    },
    "required": [
      "approvalActions",
      "backupPassphrase",
      "captchaEnable",
      "newLocationAlert",
      "passkeyLoginEnable",
      "passkeySecondFactor",
      "subSigningEnable",
      "subSigningKey",
      "tgLoginEnable"
    ],
    "type": "object"
  },
